cd /workspace/services/ingestion && cat > test_kh_future.mjs << 'EOF'
const fetch = globalThis.fetch;

const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';

const query = {
  size: 5,
  query: {
    bool: {
      must: [
        {
          range: {
            tixStartDate: {
              gte: 'now'
            }
          }
        }
      ]
    }
  },
  sort: [
    { tixStartDate: { order: 'asc' } }
  ]
};

async function test() {
  const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'User-Agent': 'EventPulse/1.0' },
    body: JSON.stringify(query)
  });

  const data = await response.json();

  // Show all dates
  console.log('All dates (as stored):');
  data.hits?.hits?.slice(0, 5).forEach((h, i) => {
    const rawDate = h._source?.tixStartDate;
    const parsed = new Date(rawDate);
    console.log(`${i+1}. Raw: ${rawDate}`);
    console.log(`   UTC: ${parsed.toISOString()}`);
    console.log(`   Date: ${parsed.toISOString().split('T')[0]}`);
  });
}

test().catch(console.error);
EOF
node test_kh_future.mjs

